import * as THREE from 'three';
import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';

// Original sculpt generated by tools/build-beast-skull.py; anatomy informed by museum specimens.
export async function createBeastSkull(){
 const root=new THREE.Group(),fossil=new THREE.Group(),habitat=new THREE.Group(),foliage=new THREE.Group();
 root.name='Leviathan — the drowned ossuary';root.add(habitat,fossil,foliage);
 let seed=137;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)|0;return (seed>>>0)/4294967296;};
 const grainData=new Uint8Array(256*256*4);
 for(let y=0;y<256;y++)for(let x=0;x<256;x++){const k=(y*256+x)*4,v=115+rand()*55+18*Math.sin(x*.24+Math.sin(y*.08))*Math.sin(y*.17);grainData[k]=grainData[k+1]=grainData[k+2]=v;grainData[k+3]=255;}
 const grain=new THREE.DataTexture(grainData,256,256);grain.wrapS=grain.wrapT=THREE.RepeatWrapping;grain.magFilter=THREE.LinearFilter;grain.minFilter=THREE.LinearMipmapLinearFilter;grain.generateMipmaps=true;grain.needsUpdate=true;
 const bone=new THREE.MeshStandardMaterial({color:0xe9e5ce,vertexColors:true,roughness:.93,bumpMap:grain,bumpScale:.015});
 const plainBone=new THREE.MeshStandardMaterial({color:0xaba18a,roughness:.96,bumpMap:grain,bumpScale:.012});
 const toothMaterial=new THREE.MeshStandardMaterial({color:0xfff2cf,vertexColors:true,roughness:.7,bumpMap:grain,bumpScale:.01});
 const mossUniform={value:1};
 // Object-space mineral weathering stays attached to the bone from every angle.
 for(const material of [bone,plainBone]){
  material.onBeforeCompile=shader=>{
   shader.uniforms.boneMoss=mossUniform;
   shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 boneP;\nvarying vec3 boneN;').replace('#include <begin_vertex>','#include <begin_vertex>\nboneP=position;boneN=normal;');
   shader.fragmentShader=shader.fragmentShader.replace('#include <common>',`#include <common>
varying vec3 boneP;varying vec3 boneN;uniform float boneMoss;
float bHash(vec3 p){p=fract(p*.1031);p+=dot(p,p.yzx+33.33);return fract((p.x+p.y)*p.z);}
float bNoise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(bHash(i),bHash(i+vec3(1,0,0)),f.x),mix(bHash(i+vec3(0,1,0)),bHash(i+vec3(1,1,0)),f.x),f.y),mix(mix(bHash(i+vec3(0,0,1)),bHash(i+vec3(1,0,1)),f.x),mix(bHash(i+vec3(0,1,1)),bHash(i+vec3(1,1,1)),f.x),f.y),f.z);}
float bFbm(vec3 p){return bNoise(p)*.56+bNoise(p*2.13+7.3)*.27+bNoise(p*4.17-3.4)*.12+bNoise(p*8.3+1.1)*.05;}
`).replace('#include <color_fragment>',`#include <color_fragment>
float mineral=bFbm(boneP*.47),pores=bNoise(boneP*9.4);
diffuseColor.rgb*=mix(vec3(.42,.40,.32),vec3(1.12,1.09,1.01),smoothstep(.17,.72,mineral));
diffuseColor.rgb*=.9+.1*smoothstep(.23,.44,pores);
float damp=(1.-smoothstep(2.,9.,boneP.y))*.4;
diffuseColor.rgb*=1.-damp;
float mossArea=smoothstep(.42,.69,mineral+.07*bNoise(boneP*2.3))*smoothstep(.1,.75,boneN.y)*smoothstep(19.,30.,boneP.y)*(1.-smoothstep(-9.,9.,boneP.x))*boneMoss;
diffuseColor.rgb=mix(diffuseColor.rgb,vec3(.13,.18,.065)*(.65+mineral*.7),mossArea*.92);
`).replace('#include <normal_fragment_maps>',`#include <normal_fragment_maps>
float relief=(bFbm(boneP*2.3)*.12+bNoise(boneP*13.1)*.025);
normal=perturbNormalArb(-vViewPosition,normal,vec2(dFdx(relief),dFdy(relief)),faceDirection);
`);
  };
  material.customProgramCacheKey=()=> 'weathered-fossil-v2';
 }
 const green=new THREE.MeshStandardMaterial({color:0x4b6538,roughness:1});
 const vegetation=[0x24482e,0x466738,0x66833d,0x829b50].map(color=>new THREE.MeshStandardMaterial({color,roughness:.95,side:THREE.DoubleSide}));
 const bark=new THREE.MeshStandardMaterial({color:0x534a34,roughness:1});
 function mesh(g,m,parent=fossil){const o=new THREE.Mesh(g,m);o.castShadow=o.receiveShadow=true;parent.add(o);return o;}
 async function loadPart(name){
  const parts=await Promise.all(['positions','indices','colors'].map(async kind=>{const response=await fetch(`./assets/beast-skull/${name}-${kind}.bin`);if(!response.ok)throw new Error(`Missing skull mesh: ${name}-${kind}`);return response.arrayBuffer();}));
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(parts[0]),3));g.setIndex(new THREE.BufferAttribute(new Uint32Array(parts[1]),1));g.setAttribute('color',new THREE.BufferAttribute(new Float32Array(parts[2]),3));g.computeVertexNormals();
  const p=g.attributes.position,uv=new Float32Array(p.count*2);for(let i=0;i<p.count;i++){uv[i*2]=p.getX(i)*.055;uv[i*2+1]=p.getY(i)*.055+p.getZ(i)*.012;}g.setAttribute('uv',new THREE.BufferAttribute(uv,2));
  const o=mesh(g,bone);o.name=name;return o;
 }
 const [cranium,mandible]=await Promise.all(['cranium','mandible'].map(loadPart));
 function sweep(points,radii,material=plainBone,parent=fossil){
  const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(...p))),n=36,k=12,frames=curve.computeFrenetFrames(n,false),v=[],uv=[],idx=[];
  for(let i=0;i<=n;i++){const t=i/n,p=curve.getPoint(t),f=t*(radii.length-1),j=Math.min(Math.floor(f),radii.length-2),r=THREE.MathUtils.lerp(radii[j],radii[j+1],f-j);for(let a=0;a<=k;a++){const angle=a/k*Math.PI*2,rad=r*(1+.035*Math.sin(a*3+i*.7)),q=p.clone().addScaledVector(frames.normals[i],Math.cos(angle)*rad).addScaledVector(frames.binormals[i],Math.sin(angle)*rad);v.push(q.x,q.y,q.z);uv.push(a/k,t*2);if(i<n&&a<k){const b=i*(k+1)+a;idx.push(b,b+k+1,b+1,b+1,b+k+1,b+k+2);}}}
  for(let i=0;i<idx.length;i+=3)[idx[i+1],idx[i+2]]=[idx[i+2],idx[i+1]];
  const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(v,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return mesh(g,material,parent);
 }
 // Teeth belong to two arc-shaped tooth rows; size, wear and missing positions vary.
 function tooth(x,y,z,length,up,index){const s=Math.sign(z),broken=index===4||index===23;const o=sweep([[x,y,z],[x-.2,y+up*length*.42,z-s*.12],[x-1,y+up*length*.8,z-s*.32],[x-1.65,y+up*length,z-s*.42]],[.66+length*.052,.52,.28,broken?.22:.025],toothMaterial);const p=o.geometry.attributes.position,col=new Float32Array(p.count*3);for(let i=0;i<p.count;i++){const t=Math.min(1,Math.abs(p.getY(i)-y)/length),stain=.67+.3*Math.sin(t*Math.PI*.5);col[i*3]=.77*stain;col[i*3+1]=.65*stain;col[i*3+2]=.44*stain;}o.geometry.setAttribute('color',new THREE.BufferAttribute(col,3));o.name=up>0?'Lower dentary tooth':'Upper maxillary tooth';}
 for(const s of [-1,1]){
  for(let i=0;i<19;i++){if(s===1&&i===13)continue;const x=-11+i*2.07+(rand()-.5)*.5,z=s*(8.1-(x+12)/43*3.8),len=(2.8+Math.sin(i/18*Math.PI)*3.3+rand()*.8)*(i===7?1.22:1);tooth(x,17.65+Math.max(0,x-22)*.26,z,len,-1,i+(s+1)*10);}
  for(let i=0;i<18;i++){if(s===-1&&i===6)continue;const x=-11+i*2.28+(rand()-.5)*.5,y=x<0?5.8-x*.25:5.1+Math.max(0,x-20)*.065,z=s*(7.7-(x+11)/42*4.4);tooth(x,y,z,2.1+Math.sin(i/17*Math.PI)*1.9+rand()*.7,1,i+12);}
 }
 // Cervical column with irregular neural spines; ribs emerge from the land behind it.
 for(let i=0;i<7;i++){
  const x=-30-i*4.1,y=11-i*.8;const g=new THREE.TorusGeometry(1.65,.72,8,14);g.rotateY(Math.PI/2);const o=mesh(g,plainBone);o.position.set(x,y,0);o.scale.set(1,1.25,1.5);
  sweep([[x,y,0],[x-1,y+3.7,0],[x-2,y+5.2,.2]],[.7,.53,.13]);
  if(i>0)for(const s of [-1,1]){const broken=i===3&&s===1,spread=1+(rand()-.5)*.16;sweep([[x,y,s*1],[x-1,y+5+rand()*2,s*7],[x+1,y+3+rand()*2,s*14*spread],[x+4,broken?6.5:2.1,s*(15-i*.35)*spread]],[1,.95,.67,broken?.48:.15]);}
 }
 // A weathered rocky shelf lies behind the jaws; the open mouth faces the water.
 const groundMat=new THREE.MeshStandardMaterial({vertexColors:true,roughness:1,bumpMap:grain,bumpScale:.23});
 const rings=28,sides=100,v=[],colors=[],ind=[];
 for(let r=0;r<=rings;r++)for(let a=0;a<=sides;a++){
  const t=r/rings,ang=a/sides*Math.PI*2,edge=1+.035*Math.sin(ang*7)+.065*Math.sin(ang*3+1),x=-24+Math.cos(ang)*44*t*edge,z=Math.sin(ang)*26*t*edge;
  const y=-2.2+6.8*Math.pow(Math.max(0,1-t),.7)+Math.sin(x*.18)*Math.sin(z*.22)*Math.sin(Math.PI*t)*1.3;
  v.push(x,y,z);const c=new THREE.Color(t>.87?0x96846b:0x44583b);c.multiplyScalar(.78+rand()*.23);colors.push(c.r,c.g,c.b);
  if(r<rings&&a<sides){const k=r*(sides+1)+a;ind.push(k,k+sides+1,k+1,k+1,k+sides+1,k+sides+2);}
 }
 for(let i=0;i<ind.length;i+=3)[ind[i+1],ind[i+2]]=[ind[i+2],ind[i+1]];
 const groundUV=[];for(let i=0;i<v.length;i+=3)groundUV.push(v[i]*.05,v[i+2]*.05);
 const groundGeo=new THREE.BufferGeometry();groundGeo.setAttribute('position',new THREE.Float32BufferAttribute(v,3));groundGeo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));groundGeo.setAttribute('uv',new THREE.Float32BufferAttribute(groundUV,2));groundGeo.setIndex(ind);groundGeo.computeVertexNormals();mesh(groundGeo,groundMat,habitat);
 // Moss is thin and follows the original bone surface, leaving the fenestrae open.
 const p=cranium.geometry.attributes.position,n=cranium.geometry.attributes.normal;
 function leaf(p,angle,length,width,mat){const verts=[],ids=[];const dir=new THREE.Vector3(Math.cos(angle),0,Math.sin(angle)),cross=new THREE.Vector3(-dir.z,0,dir.x);for(let j=0;j<=8;j++){const t=j/8,center=new THREE.Vector3(...p).addScaledVector(dir,length*t);center.y+=Math.sin(t*Math.PI)*length*.24-t*t*length*.28;const w=Math.sin(t*Math.PI)*width;for(const side of [-1,0,1]){const q=center.clone().addScaledVector(cross,w*side);if(side===0)q.y+=width*.12;verts.push(q.x,q.y,q.z);}if(j<8){const k=j*3;ids.push(k,k+3,k+1,k+1,k+3,k+4,k+1,k+4,k+2,k+2,k+4,k+5);}}
 const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(ids);g.computeVertexNormals();mesh(g,mat,foliage);}
 function fern(x,y,z,scale){for(let i=0;i<9;i++)leaf([x,y,z],i*.698+rand()*.12,scale*(.8+rand()*.3),scale*.12,vegetation[i%4]);}
 let crownPlants=0;for(let i=0;i<p.count&&crownPlants<65;i+=127){if(p.getX(i)>-9||p.getY(i)<30||n.getY(i)<.75)continue;fern(p.getX(i),p.getY(i)+.02,p.getZ(i),.75+rand()*1.1);crownPlants++;}
 for(let i=0;i<110;i++){const x=-61+rand()*49,z=(rand()-.5)*37;fern(x,1.7+Math.max(0,1-Math.abs(z)/22)*1.6,z,1.1+rand()*1.4);}
 for(let i=0;i<13;i++){const x=-34-rand()*25,z=(rand()>.5?1:-1)*(9+rand()*8),height=8+rand()*7;const top=[x+1,height,z-.5];sweep([[x,2,z],[x+.2,height*.6,z],top],[.36,.26,.12],bark,foliage);for(let a=0;a<9;a++)leaf(top,a*Math.PI*2/9+i,4+rand()*1.4,.5,vegetation[a%4]);}
 // Trailing vines on the posterior face, kept clear of eye and antorbital openings.
 for(let i=0;i<12;i++){const s=i%2?1:-1,x=-25+rand()*8;const top=[x,30+rand()*3,s*6];sweep([top,[x+1,27,s*8.5],[x+1.5,21,s*9.1],[x+2.1,16-rand()*5,s*9]],[.1,.09,.07,.015],green,foliage);for(let k=0;k<4;k++)leaf([x+1.5,25-k*2,s*9.1],s*Math.PI*.5+rand()*.5,.65,.24,vegetation[k%4]);}
 // Thin branching sutures follow the actual surface, with no line across a bone window.
 const crackMat=new THREE.MeshStandardMaterial({color:0x514939,roughness:1});
 cranium.updateMatrixWorld(true);const ray=new THREE.Raycaster();
 for(const side of [-1,1])for(const [cx,cy,span] of [[20,27,4],[15,27.5,4.5],[-5,30.5,3],[-18,33,4],[-2,21,2],[29,23,2],[-23,29,3]]){
  let segment=[];for(let j=0;j<12;j++){const x=cx-j*span/12+(rand()-.5)*.35,y=cy-j*.32+(rand()-.5)*.24;ray.set(new THREE.Vector3(x,y,side*25),new THREE.Vector3(0,0,-side));const hit=ray.intersectObject(cranium,false)[0];if(hit){segment.push([hit.point.x,hit.point.y,hit.point.z+side*.025]);}else {if(segment.length>2)sweep(segment,[.028,.055,.018],crackMat);segment=[];}}if(segment.length>2)sweep(segment,[.028,.05,.018],crackMat);
 }
 // Static leaves, teeth and ribs share batches instead of issuing thousands of draw calls.
 for(const parent of [fossil,foliage]){
  const batches=new Map();for(const child of [...parent.children]){if(!child.isMesh||child===cranium||child===mandible)continue;const key=child.material.uuid+Object.keys(child.geometry.attributes).sort().join(',');if(!batches.has(key))batches.set(key,[]);batches.get(key).push(child);}
  for(const children of batches.values()){if(children.length<2)continue;const geometries=children.map(child=>{child.updateMatrix();return child.geometry.clone().applyMatrix4(child.matrix);});const merged=mergeGeometries(geometries);if(!merged){geometries.forEach(g=>g.dispose());continue;}const combined=mesh(merged,children[0].material,parent);combined.name='Static fossil / vegetation batch';for(const child of children){parent.remove(child);child.geometry.dispose();}geometries.forEach(g=>g.dispose());}
 }
 return {root,fossil,habitat,foliage,cranium,mandible,bone,plainBone,toothMaterial,mossUniform};
}
